from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int], *, max_workers: int | None = None) -> list[int]:
    """Return the parity of each element of xs, computed in a thread pool.

    The result is in the same order as xs. The output does not depend on
    max_workers; it only controls how many threads are used. max_workers=None
    uses the ThreadPoolExecutor default.
    """
    with ThreadPoolExecutor(max_workers=max_workers) as ex:
        return list(ex.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4]) == [0, 1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, -3]) == [1, 0, 1]


def test_parities_preserves_order() -> None:
    xs = list(range(1000))
    assert parities(xs) == [x % 2 for x in xs]


@pytest.mark.parametrize("workers", [1, 2, 4, 16])
def test_parities_independent_of_worker_count(workers: int) -> None:
    xs = [7, 10, -3, 0, 22, 91, -8]
    expected = [parity(x) for x in xs]
    assert parities(xs, max_workers=workers) == expected


def test_parities_returns_new_list() -> None:
    xs = [1, 2, 3]
    out = parities(xs)
    assert out is not xs
    assert xs == [1, 2, 3]
